package com.aistock.prediction.maas;
import com.aistock.common.BusinessException;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.sql.Timestamp;import java.time.*;import java.util.*;
/** One DB slot for every kind of paid MaaS operation. Caller commits before network IO. */
public final class MaasOperationGate {
 private final JdbcTemplate jdbc;public MaasOperationGate(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public Map<String,Object> lock(Instant now){var slot=jdbc.queryForMap("select * from prediction_explanation_slot where slot_id=1 for update");if(slot.get("operation_id")!=null&&(!now.isBefore(instant(slot.get("lease_until")))||portfolioExpired(slot,now))){String kind=String.valueOf(slot.get("operation_kind"));String table=switch(kind){case "PREDICTION_EXPLANATION","null"->"prediction_explanation_operation";case "STOCK_ANALYSIS"->"stock_analysis_operation";case "STOCK_QUESTION"->"stock_question_operation";case "COMPARISON_EXPLANATION"->"comparison_ai_operation";case "PORTFOLIO_QUESTION"->"portfolio_question_operation";default->throw new IllegalStateException("Unknown MaaS slot kind");};String fence="STOCK_ANALYSIS".equals(kind)?",fencing_revision=fencing_revision+1":"";jdbc.update("update "+table+" set state='FAILED',error_code='AI_INTERRUPTED',finished_at=?"+fence+" where operation_id=? and state='RUNNING'",ts(now),slot.get("operation_id"));jdbc.update("update prediction_explanation_slot set operation_id=null,lease_until=null,operation_kind=null where slot_id=1");slot=new HashMap<>(slot);slot.put("operation_id",null);slot.put("operation_kind",null);}return slot;}
 private boolean portfolioExpired(Map<String,Object> slot,Instant now){if(!"PORTFOLIO_QUESTION".equals(slot.get("operation_kind")))return false;var dates=jdbc.queryForList("select deadline_at from portfolio_question_operation where operation_id=? and state='RUNNING'",slot.get("operation_id"));return !dates.isEmpty()&&!now.isBefore(instant(dates.get(0).get("deadline_at")));}
 public void lockAndAcquire(String kind,UUID op,Instant now){if(!Set.of("PREDICTION_EXPLANATION","STOCK_ANALYSIS","STOCK_QUESTION","COMPARISON_EXPLANATION","PORTFOLIO_QUESTION").contains(kind))throw new IllegalArgumentException("Unknown operation kind");var tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);tx.execute(s->{var slot=lock(now);if(slot.get("operation_id")!=null)throw new BusinessException("AI_BUSY","AI正在处理其他请求，请稍后重试",HttpStatus.SERVICE_UNAVAILABLE);jdbc.update("update prediction_explanation_slot set operation_id=?,lease_until=?,operation_kind=? where slot_id=1",op.toString(),ts(now.plusSeconds(50)),kind);return null;});}
 public boolean owns(Map<String,Object> slot,String kind,UUID op){return op.toString().equals(slot.get("operation_id"))&&kind.equals(slot.get("operation_kind"));}
 public void release(String kind,UUID op){jdbc.update("update prediction_explanation_slot set operation_id=null,lease_until=null,operation_kind=null where slot_id=1 and operation_id=? and operation_kind=?",op.toString(),kind);}
 public static Instant instant(Object v){return v instanceof Timestamp t?t.toInstant():((LocalDateTime)v).toInstant(ZoneOffset.UTC);}
 public static Timestamp ts(Instant t){return Timestamp.from(t.truncatedTo(java.time.temporal.ChronoUnit.MILLIS));}
}